const upsertEnv = `-- name: UpsertEnv :exec
INSERT INTO env_vars (app_id, key, value_enc, updated_at) VALUES (?, ?, ?, ?)
ON CONFLICT (app_id, key) DO UPDATE SET value_enc = excluded.value_enc, updated_at = excluded.updated_at
`

type UpsertEnvParams struct {
	AppID     int64
	Key       string
	ValueEnc  []byte
	UpdatedAt int64
}

func (q *Queries) UpsertEnv(ctx context.Context, arg UpsertEnvParams) error {
	_, err := q.db.ExecContext(ctx, upsertEnv,
		arg.AppID,
		arg.Key,
		arg.ValueEnc,
		arg.UpdatedAt,
	)
	return err
}
